package es.gestionpersonas.seguridad.servicio;
import es.gestionpersonas.comun.*; import es.gestionpersonas.cuenta.modelo.CuentaUsuario; import es.gestionpersonas.cuenta.repositorio.RepositorioCuentaUsuario; import es.gestionpersonas.entidad.modelo.ContactoEntidad; import es.gestionpersonas.entidad.repositorio.RepositorioContactoEntidad; import es.gestionpersonas.seguridad.dto.MfaDtos; import es.gestionpersonas.seguridad.modelo.*; import es.gestionpersonas.seguridad.repositorio.*; import es.gestionpersonas.seguridad.web.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*;
@Service @Transactional(readOnly=true)
public class ServicioMfa {
 private final RepositorioSesionAutenticacion sesiones; private final RepositorioDesafioMfa desafios; private final RepositorioCuentaUsuario cuentas; private final RepositorioContactoEntidad contactos; private final ServicioPoliticaMfa politicas; private final ProveedorEntregaMfa entrega; private final SecureRandom random=new SecureRandom(); private final int minutosDesafio,maxIntentos,maxValidez; private final String baseEnlace;
 public ServicioMfa(RepositorioSesionAutenticacion s,RepositorioDesafioMfa d,RepositorioCuentaUsuario c,RepositorioContactoEntidad co,ServicioPoliticaMfa p,ProveedorEntregaMfa e,@Value("${app.mfa.challenge-minutes:10}")int md,@Value("${app.mfa.max-attempts:5}")int mi,@Value("${app.mfa.max-validity-minutes:480}")int mv,@Value("${app.mfa.link-base-url:http://localhost:5173/mfa/verificar}")String be){sesiones=s;desafios=d;cuentas=c;contactos=co;politicas=p;entrega=e;minutosDesafio=md;maxIntentos=mi;maxValidez=mv;baseEnlace=be;}
 public void exigirContexto(AccesoActual a){politicas.minutosContexto(a).ifPresent(m->exigir(a.sessionId(),m));}
 public void exigirPermiso(AccesoActual a,String permiso){politicas.minutosPermiso(a,permiso).ifPresent(m->exigir(a.sessionId(),m));}
 private void exigir(Long sesionId,int minutos){SesionAutenticacion s=sesion(sesionId);if(!s.mfaVigente(LocalDateTime.now().withNano(0),minutos))throw new ExcepcionMfaRequerida("Autenticación multifactor requerida");}
 public MfaDtos.EstadoMfa estado(Long sesionId){SesionAutenticacion s=sesion(sesionId);CuentaUsuario c=cuenta(s);return new MfaDtos.EstadoMfa(s.getAuthenticationLevel(),s.getMfaVerifiedAt(),s.getMfaValidUntil(),opciones(c));}
 @Transactional public MfaDtos.RespuestaDesafio crear(Long sesionId,MfaDtos.SolicitudDesafio in){SesionAutenticacion s=sesion(sesionId);CuentaUsuario c=cuenta(s);String canal=in.canal().trim().toUpperCase();String mecanismo=in.mecanismo().trim().toUpperCase();if(!Set.of("EMAIL","SMS").contains(canal))throw new IllegalArgumentException("Canal MFA debe ser EMAIL o SMS");if(!Set.of("CODIGO","ENLACE").contains(mecanismo))throw new IllegalArgumentException("Mecanismo MFA debe ser CODIGO o ENLACE");String destino=destino(c,canal);for(DesafioMfa x:desafios.findBySesionIdOrderByIdDesc(sesionId))if(x.activa(LocalDateTime.now().withNano(0)))x.invalidar();String secreto="CODIGO".equals(mecanismo)?codigo():token();LocalDateTime exp=LocalDateTime.now().withNano(0).plusMinutes(minutosDesafio);DesafioMfa d=desafios.save(new DesafioMfa(sesionId,c.getId(),canal,mecanismo,enmascarar(canal,destino),sha256(secreto),exp,maxIntentos));if("CODIGO".equals(mecanismo))entrega.enviarCodigo(canal,destino,secreto,minutosDesafio);else entrega.enviarEnlace(canal,destino,baseEnlace+"?desafio="+d.getId()+"&token="+secreto,minutosDesafio);return new MfaDtos.RespuestaDesafio(d.getId(),canal,mecanismo,d.getDestinoEnmascarado(),exp);}
 @Transactional public MfaDtos.RespuestaVerificacion verificarCodigo(Long sesionId,MfaDtos.VerificarCodigo in){return verificar(sesionId,in.desafioId(),in.codigo(),"CODIGO");}
 @Transactional public MfaDtos.RespuestaVerificacion verificarEnlace(Long sesionId,MfaDtos.VerificarEnlace in){return verificar(sesionId,in.desafioId(),in.token(),"ENLACE");}
 private MfaDtos.RespuestaVerificacion verificar(Long sesionId,Long id,String secreto,String mecanismo){SesionAutenticacion s=sesion(sesionId);DesafioMfa d=desafios.findByIdAndSesionId(id,sesionId).orElseThrow(()->new ExcepcionNoEncontrado("Desafío MFA no encontrado"));LocalDateTime ahora=LocalDateTime.now().withNano(0);if(!d.activa(ahora))throw new ExcepcionProhibido("El desafío MFA ha caducado, fue consumido o está bloqueado");if(!mecanismo.equals(d.getMecanismo()))throw new IllegalArgumentException("Mecanismo MFA incorrecto");if(!MessageDigest.isEqual(sha256(secreto.trim()).getBytes(StandardCharsets.US_ASCII),d.getHashSecreto().getBytes(StandardCharsets.US_ASCII))){d.fallo();throw new ExcepcionProhibido("Código o enlace MFA incorrecto");}d.consumir();s.reforzarMfa(ahora.plusMinutes(maxValidez));return new MfaDtos.RespuestaVerificacion(true,s.getAuthenticationLevel(),s.getMfaVerifiedAt(),s.getMfaValidUntil());}
 private SesionAutenticacion sesion(Long id){return sesiones.findById(id).orElseThrow(()->new ExcepcionNoAutorizado("Sesión no válida"));}
 private CuentaUsuario cuenta(SesionAutenticacion s){return cuentas.findById(s.getAccountId()).orElseThrow(()->new ExcepcionNoAutorizado("Cuenta no válida"));}
 private List<MfaDtos.OpcionCanal> opciones(CuentaUsuario c){List<MfaDtos.OpcionCanal> r=new ArrayList<>();if(c.getLoginEmail()!=null&&!c.getLoginEmail().isBlank())r.add(new MfaDtos.OpcionCanal("EMAIL",enmascarar("EMAIL",c.getLoginEmail()),List.of("CODIGO","ENLACE")));try{String t=destino(c,"SMS");r.add(new MfaDtos.OpcionCanal("SMS",enmascarar("SMS",t),List.of("CODIGO","ENLACE")));}catch(RuntimeException ignored){}return r;}
 private String destino(CuentaUsuario c,String canal){if("EMAIL".equals(canal)){if(c.getLoginEmail()==null||c.getLoginEmail().isBlank())throw new ExcepcionConflicto("La cuenta no tiene correo de acceso asociado");return c.getLoginEmail();}if(c.getPersonEntityId()==null)throw new ExcepcionConflicto("La cuenta no está asociada a una persona con teléfono");List<ContactoEntidad> l=contactos.findByEntityIdAndContactTypeAndActiveTrueAndPreferredTrue(c.getPersonEntityId(),"TELEFONO");if(l.isEmpty())l=contactos.findByEntityIdOrderByContactTypeAscPreferredDescIdAsc(c.getPersonEntityId()).stream().filter(x->x.isActive()&&Set.of("TELEFONO","MOVIL").contains(x.getContactType().toUpperCase())).toList();if(l.isEmpty())throw new ExcepcionConflicto("La cuenta no tiene teléfono móvil asociado");return l.get(0).getContactValue();}
 private String codigo(){return String.format("%06d",random.nextInt(1_000_000));} private String token(){byte[]b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
 private String sha256(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private String enmascarar(String canal,String v){if("EMAIL".equals(canal)){int a=v.indexOf('@');if(a<=1)return "***"+(a>=0?v.substring(a):"");return v.substring(0,1)+"***"+v.substring(a);}String d=v.replaceAll("\\s+","");return d.length()<=4?"****":"***"+d.substring(d.length()-4);}
}
